<template>
  <div class="funds">
    <section class="panel lead"><div><span class="eyebrow">成交 / 份额 / 披露分开核对</span><h2>宽基资金观察</h2><p>固定 10 只 ETF，覆盖 4 个指数方向。价格和份额可以观察，买方身份需要独立证据。</p></div><div class="tools"><button :disabled="loading" @click="refresh">刷新记录</button><button :disabled="syncing || !!result && !result.job.can_start" @click="sync">核对最新资料</button><router-link :to="{path:'/',query:{tab:'short-term',mode:'close',date}}">收盘提醒 →</router-link></div></section>
    <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message notice" role="status">{{ notice }}</p><p v-if="loading && !result" class="empty">正在读取本地观察记录…</p>
    <template v-if="result">
      <p v-if="pinnedBatch" class="message notice">正在查看触发时保存的快照 #{{ pinnedBatch }}。<button @click="router.replace({query:{...route.query,fund_batch:undefined}})">查看最新快照</button></p><section class="panel status"><div class="tools"><b>所选 {{ date }}</b><span v-if="data">成交数据 {{ data.market_date || '未取得' }} · 份额估算 {{ data.flow_date || '未取得' }}</span><span v-else>尚无覆盖该日期的已校验快照</span></div><p v-if="data">快照 #{{ data.batch_id }} · 采集 {{ time(data.fetched_at) }}<template v-if="data.market_date!==date || data.flow_date!==date">。各渠道日期分别列出，未将较早资料当作所选日的新数据。</template></p><p v-if="result.check" :class="{notice:result.check.status!=='ready'}">{{ result.check.message }}<template v-if="result.check.waiting_until"> 预计等候窗口至 {{ time(result.check.waiting_until) }}。</template></p><p v-if="['running','queued'].includes(result.job.status)" class="notice">后台核对{{ result.job.status==='queued'?'已提交':'运行中' }}，正在等待真实结果。</p><p v-else-if="['error','partial','unknown','interrupted'].includes(result.job.status)" class="notice">任务状态：{{ result.job.message }}</p><small>本页刷新只读本地记录。份额、净值通常较晚发布，次日上午继续补漏；资料缺失不补零。</small></section>
      <div class="metrics"><div class="panel"><span>成交放大</span><b>{{ data?data.spikes:'—' }}<small> / 10 只</small></b><small>较前20日中位数 ≥ 2倍且 ≥ 1亿元</small></div><div class="panel"><span>份额估算覆盖</span><b>{{ data?data.flow_valid:'—' }}<small> / 10 只</small></b><small>份额、同日净值及因子均须可用</small></div><div class="panel"><span>篮子净变动对应金额估算</span><b :class="tone(data?.estimate)">{{ amount(data?.estimate) }}</b><small>{{ data?.flow_date || '待取得' }} · 样本不全时总额留空</small></div><div class="panel"><span>已登记的披露</span><b>{{ result.evidence_count }}<small> 条</small></b><small>人工核对来源，独立于资金估算</small></div></div>
      <template v-if="data">
        <section class="panel"><div class="section-head"><h3>指数方向</h3><span>仅合计本方向的固定观察样本</span></div><div class="groups"><button v-for="group in data.groups" :key="group.name" :class="{selected:filter===group.name}" @click="filter=filter===group.name?'':group.name"><strong>{{ group.name }}</strong><b :class="tone(group.estimate)">{{ amount(group.estimate) }}</b><small>估算覆盖 {{ group.flow_valid }}/{{ group.funds }} · 放量 {{ group.spikes }} 只</small><small>{{ group.positive_days>=5?'最近5个交易日均净增加':'连续净增加 '+group.positive_days+' 个交易日' }}{{ !group.streak_ready?' · 连续性资料不足':'' }}</small></button></div></section>
        <section class="panel"><div class="section-head"><h3>基金明细</h3><select v-model="filter" aria-label="观察方向"><option value="">全部方向</option><option v-for="group in data.groups" :key="group.name">{{ group.name }}</option></select></div><div class="table-wrap"><table><thead><tr><th>ETF / 指数</th><th>复权日变化</th><th>成交额 / 放大倍数</th><th>份额净变动</th><th>单位净值 / 披露日</th><th>金额估算</th><th>买方身份</th><th>核对</th></tr></thead><tbody><tr v-for="fund in members" :key="fund.ts_code"><td><b>{{ fund.name }}</b><small>{{ fund.code }} · {{ fund.group }}</small></td><td :class="tone(fund.market?.change_pct)">{{ pct(fund.market?.change_pct) }}</td><td>{{ amount(fund.market?.amount) }}<small :class="{notice:fund.market?.amount_spike}">{{ multiple(fund.market?.amount_multiple) }} · 基准 {{ amount(fund.market?.amount_baseline) }}</small></td><td :class="tone(fund.flow?.share_delta)" :title="fund.flow?.share_delta || ''">{{ shares(fund.flow?.share_delta) }}</td><td>{{ decimal(fund.flow?.nav,4) }}<small>{{ fund.flow?.nav_ann_date || '净值披露日未知' }}</small></td><td :class="tone(fund.flow?.estimate)">{{ amount(fund.flow?.estimate) }}<small v-for="line in fund.flow?.missing || ['份额或净值资料尚未齐备']" :key="line" class="notice">{{ line }}</small></td><td>未知<small>不由放量或份额变化认定</small></td><td><button @click="openHistory(fund)">20日记录</button><button @click="focusEvidence(fund.ts_code)">查看披露</button></td></tr></tbody></table></div><p class="note">{{ data.method }}</p><small>{{ data.limitation }}</small></section>
        <section v-if="historyName" ref="historyPanel" class="panel history"><div class="section-head"><h3>{{ historyName }} · 近20交易日记录</h3><button @click="closeHistory">收起</button></div><p v-if="historyLoading">正在读取快照…</p><template v-else-if="history"><p class="note">保存快照 #{{ history.batch_id }} · 采集 {{ time(history.fetched_at) }}；日期、基准与金额均来自同一快照。</p><div class="table-wrap"><table><thead><tr><th>交易日</th><th>成交额 / 放大倍数</th><th>总份额</th><th>前日份额 / 日期</th><th>同日单位净值</th><th>净变动金额估算</th><th>复权因子核对</th></tr></thead><tbody><tr v-for="point in history.items" :key="point.date"><td>{{ point.date }}</td><td>{{ amount(point.amount) }}<small>{{ multiple(point.amount_multiple) }}</small></td><td :title="point.shares || ''">{{ shares(point.shares) }}</td><td :title="point.prior_shares || ''">{{ shares(point.prior_shares) }}<small>{{ point.prior_date || '—' }}</small></td><td>{{ decimal(point.nav,4) }}<small>披露 {{ point.nav_ann_date || '—' }}</small></td><td :class="tone(point.estimate)">{{ amount(point.estimate) }}<small v-for="line in point.missing" :key="line" class="notice">{{ line }}</small></td><td>{{ point.prior_factor || '未知' }} → {{ point.factor || '未知' }}</td></tr></tbody></table></div></template></section>
        <details class="panel"><summary>数据覆盖、规则及局限</summary><p>{{ data.note }}</p><p>成交异动需 20 个相邻真实交易日的有效成交额作比较。多方向提醒需至少 3 只 ETF、跨 2 个方向同时放量；连续份额提醒需方向内全部样本连续 3 日估算净增加且当日 ≥ 5000 万元。资料不足时不判断解除。</p><p>份额变化可包含实物申赎和套利；二级市场成交不必然改变基金总份额。“未知”不等于零，也不能视为资金退出。</p><p v-if="data.issues.length" class="notice">本快照有 {{ data.issues.length }} 项源数据待核对：</p><ul><li v-for="line in data.issues.slice(0,30)" :key="line">{{ line }}</li></ul><small v-if="data.issues.length>30">仅列出前30项；相关金额均保留未知。</small></details>
      </template>
      <section ref="evidencePanel" class="panel evidence"><div class="section-head"><div><h3>实名披露 · 人工登记核对</h3><small>公告、增持计划、持仓报告分别记录；不将基金整体估算归给披露主体。</small></div><button @click="formOpen=!formOpen">{{ formOpen?'收起登记':'登记官方披露' }}</button></div><div class="tools"><select v-model="evidenceCode" aria-label="披露基金范围"><option value="">全部登记</option><option value="market">仅市场整体公告</option><option v-for="member in data?.members || []" :key="member.ts_code" :value="member.ts_code">{{ member.name }}</option></select><label><input type="checkbox" v-model="includeWithdrawn" />包含已撤回</label><small>股票名称或基金代码未在原文明确出现时，不指定该基金。</small></div><p class="note">{{ evidence?.note }}</p>
        <form v-if="formOpen" class="evidence-form" @submit.prevent="saveEvidence"><fieldset :disabled="!!working"><div class="form-grid"><label>原文主体<input v-model="form.subject" maxlength="100" required placeholder="如中央汇金投资有限责任公司" /></label><label>披露性质<select v-model="form.kind"><option value="bought">原文明示已买入／增持</option><option value="plan">未来增持计划／意向</option><option value="holding">报告期末持仓披露</option></select></label><label>公告日期<input type="date" v-model="form.publication_date" :max="today" required /></label><label>报告期末／资料截至日<input type="date" v-model="reportDate" :max="form.publication_date" :required="form.kind==='holding'" /></label></div><label>官方原文链接<input type="url" v-model="form.source_url" maxlength="2000" required placeholder="汇金、证金、沪深交易所或证监会网站" /></label><label>原文标题<input v-model="form.title" maxlength="200" required /></label><label>已核对的事实摘要<textarea v-model="form.summary" maxlength="1500" rows="3" required placeholder="原文明示了什么？未披露的金额、交易日或具体基金不要补推。" /></label><div class="scope"><span>原文明示的基金（未明确则不选，登记为市场整体披露）：</span><label v-for="member in data?.members || []" :key="member.ts_code"><input type="checkbox" v-model="form.codes" :value="member.ts_code" />{{ member.name }}</label></div><label class="confirm"><input type="checkbox" v-model="form.confirmed" required />我已打开原文核对主体、日期、性质和基金范围。系统只保存登记，不自动验证网站或将行情认定为该主体交易。</label><button type="submit">确认保存登记</button></fieldset></form>
        <p v-if="evidenceLoading">正在读取登记…</p><article v-for="item in visibleEvidence" :key="item.id" class="evidence-item"><div class="tools"><span class="badge">{{ kinds[item.kind] }}</span><strong>{{ item.subject }}</strong><span v-if="!item.active" class="notice">已撤回</span></div><p><a :href="item.source_url" target="_blank" rel="noopener noreferrer">{{ item.title }} ↗</a></p><p>{{ item.summary }}</p><small>公告 {{ item.publication_date }}{{ item.report_date?' · 资料截至 '+item.report_date:'' }} · {{ item.codes.length?'原文明示：'+item.codes.join('、'):'市场整体披露，未指向具体 ETF' }}</small><small>实际登记 {{ time(item.created_at) }} · {{ item.verification }}</small><p v-if="item.withdraw_reason" class="notice">撤回原因：{{ item.withdraw_reason }}</p><div class="tools"><button @click="openEvidenceHistory(item.id)">登记历史</button><button v-if="item.active" :disabled="!!working" @click="withdrawId=item.id;withdrawReason=''">撤回登记</button></div><form v-if="withdrawId===item.id" class="tools" @submit.prevent="withdrawEvidence"><input v-model="withdrawReason" maxlength="500" required placeholder="请说明撤回原因，历史保留" /><button :disabled="!!working">确认撤回</button><button type="button" @click="withdrawId=0">取消</button></form><div v-if="evidenceHistoryId===item.id"><p v-if="evidenceHistoryLoading">正在读取历史…</p><p v-for="version in evidenceHistory?.items || []" :key="version.id">{{ time(version.created_at) }} · {{ version.active?'登记／恢复':'撤回' }} {{ version.withdraw_reason }}</p><div v-if="evidenceHistory && evidenceHistory.pages>1" class="tools"><button :disabled="evidenceHistory.page<=1" @click="loadEvidenceHistory(evidenceHistory.page-1)">上一页</button><span>{{ evidenceHistory.page }}/{{ evidenceHistory.pages }}</span><button :disabled="evidenceHistory.page>=evidenceHistory.pages" @click="loadEvidenceHistory(evidenceHistory.page+1)">下一页</button></div></div></article><p v-if="!evidenceLoading && !visibleEvidence.length" class="empty">当前筛选范围内暂无登记。资金异动仍只能说明交易变化，买方身份保持未知。</p><div v-if="evidence && evidence.pages>1" class="tools pager"><button :disabled="evidencePage<=1||evidenceLoading" @click="evidencePage--">上一页</button><span>{{ evidence.page }}/{{ evidence.pages }} · 共 {{ evidence.total }} 条</span><button :disabled="evidencePage>=evidence.pages||evidenceLoading" @click="evidencePage++">下一页</button></div>
      </section>
    </template>
  </div>
</template>

<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {createLatestLoader} from '../utils/latestLoader'
import {fetchBroadFunds,fetchBroadFundHistory,syncBroadFunds,fetchFundEvidence,saveFundEvidence,withdrawFundEvidence,fetchFundEvidenceHistory} from '../api/client'
import type {BroadFundDashboard,BroadFundMember,FundEvidencePage,FundEvidenceInput} from '../api/client'
const props=defineProps<{date:string}>(),today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())
const route=useRoute(),router=useRouter(),pinnedBatch=computed(()=>{const value=Number(route.query.fund_batch);return Number.isInteger(value)&&value>0?value:undefined})
const result=ref<BroadFundDashboard|null>(null),data=computed(()=>result.value?.data),loading=ref(false),error=ref(''),notice=ref(''),working=ref(''),syncing=ref(false),filter=ref('')
const members=computed(()=>data.value?.members.filter(row=>!filter.value||row.group===filter.value)||[])
const historyName=ref(''),history=ref<Awaited<ReturnType<typeof fetchBroadFundHistory>>|null>(null),historyLoading=ref(false),historyPanel=ref<HTMLElement|null>(null)
const evidence=ref<FundEvidencePage|null>(null),evidenceLoading=ref(false),evidencePage=ref(1),includeWithdrawn=ref(false),evidenceCode=ref(''),evidencePanel=ref<HTMLElement|null>(null)
const formOpen=ref(false),reportDate=ref(''),form=ref<FundEvidenceInput>({subject:'',kind:'bought',publication_date:today,report_date:null,codes:[],source_url:'',title:'',summary:'',confirmed:false})
const withdrawId=ref(0),withdrawReason=ref(''),evidenceHistoryId=ref(0),evidenceHistory=ref<FundEvidencePage|null>(null),evidenceHistoryLoading=ref(false)
const kinds:Record<string,string>={bought:'原文明示已买入',plan:'未来计划／意向',holding:'报告期末持仓'}
const visibleEvidence=computed(()=>evidence.value?.items||[])
let disposed=false,generation=0,timer:ReturnType<typeof setInterval>|undefined
const loader=createLatestLoader<BroadFundDashboard>({pending:value=>loading.value=value,resolve:value=>result.value=value,reject:()=>error.value='宽基资料读取失败，请刷新重试。'})
const historyLoader=createLatestLoader<Awaited<ReturnType<typeof fetchBroadFundHistory>>>({pending:value=>historyLoading.value=value,resolve:value=>history.value=value,reject:()=>error.value='基金历史读取失败，请重试。'})
const evidenceLoader=createLatestLoader<FundEvidencePage>({pending:value=>evidenceLoading.value=value,resolve:value=>{evidence.value=value;evidencePage.value=value.page},reject:()=>error.value='披露登记读取失败，请重试。'})
const evidenceHistoryLoader=createLatestLoader<FundEvidencePage>({pending:value=>evidenceHistoryLoading.value=value,resolve:value=>evidenceHistory.value=value,reject:()=>error.value='登记历史读取失败，请重试。'})
function amount(value?:string|null){if(value==null)return '未知';const n=Number(value);if(!Number.isFinite(n))return '未知';return (n/(Math.abs(n)>=1e8?1e8:1e4)).toLocaleString('zh-CN',{maximumFractionDigits:2})+(Math.abs(n)>=1e8?' 亿':' 万')}
function shares(value?:string|null){return value==null?'未知':(Number(value)/10000).toLocaleString('zh-CN',{maximumFractionDigits:4})+' 万份'}
function decimal(value?:string|null,digits=2){return value==null?'未知':Number(value).toLocaleString('zh-CN',{minimumFractionDigits:digits,maximumFractionDigits:digits})}
function pct(value?:string|null){return value==null?'—':Number(value).toFixed(2)+'%'}
function multiple(value?:string|null){return value==null?'基准不足':Number(value).toFixed(2)+' 倍'}
function tone(value?:string|null){return value==null?'muted':Number(value)>0?'up':Number(value)<0?'down':'muted'}
function time(value:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
function message(e:any,fallback:string){const detail=e?.response?.data?.detail;return typeof detail==='string'?detail:Array.isArray(detail)&&typeof detail[0]?.msg==='string'?detail[0].msg.replace(/^Value error, /,''):fallback}
function refresh(){error.value='';return loader.load(signal=>fetchBroadFunds(props.date,pinnedBatch.value,signal))}
function loadEvidence(){return evidenceLoader.load(signal=>fetchFundEvidence(props.date,evidencePage.value,includeWithdrawn.value,evidenceCode.value,signal))}
async function sync(){if(syncing.value)return;const current=generation;syncing.value=true;try{const value=await syncBroadFunds();if(disposed||current!==generation)return;notice.value=value.accepted?'后台核对已提交，正在等待结果。':'复用正在执行或刚提交的任务。';await refresh()}catch(e){if(!disposed&&current===generation)error.value=message(e,'提交结果未确认，请刷新状态核对。')}finally{if(current===generation)syncing.value=false}}
async function openHistory(member:BroadFundMember){if(!data.value)return;historyName.value=member.name;history.value=null;await historyLoader.load(signal=>fetchBroadFundHistory(member.ts_code,props.date,data.value!.batch_id,signal));await nextTick();historyPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
function closeHistory(){historyLoader.cancel();historyName.value='';history.value=null}
async function focusEvidence(code:string){evidenceCode.value=code;await nextTick();evidencePanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
async function saveEvidence(){if(working.value)return;const current=generation;working.value='evidence';error.value='';try{const saved=await saveFundEvidence({...form.value,report_date:reportDate.value||null});if(disposed||current!==generation)return;formOpen.value=false;form.value={subject:'',kind:'bought',publication_date:today,report_date:null,codes:[],source_url:'',title:'',summary:'',confirmed:false};reportDate.value='';notice.value='披露已登记，公告日 '+saved.publication_date+'；按当前日期筛选显示，未改变任何基金的买方身份判断。';await Promise.all([refresh(),loadEvidence()])}catch(e){if(!disposed&&current===generation)error.value=message(e,'登记未确认，请核对必填项、官方域名与日期后重试。')}finally{if(current===generation)working.value=''}}
async function withdrawEvidence(){if(working.value||!withdrawId.value)return;const current=generation;working.value='withdraw';try{await withdrawFundEvidence(withdrawId.value,withdrawReason.value);if(disposed||current!==generation)return;withdrawId.value=0;notice.value='已撤回当前登记，原文与登记历史保留。';await Promise.all([refresh(),loadEvidence()])}catch(e){if(!disposed&&current===generation)error.value=message(e,'撤回结果未确认，请刷新核对。')}finally{if(current===generation)working.value=''}}
function loadEvidenceHistory(page=1){return evidenceHistoryLoader.load(signal=>fetchFundEvidenceHistory(evidenceHistoryId.value,page,signal))}
function openEvidenceHistory(id:number){if(evidenceHistoryId.value===id){evidenceHistoryId.value=0;evidenceHistoryLoader.cancel();return}evidenceHistoryId.value=id;evidenceHistory.value=null;loadEvidenceHistory()}
watch([includeWithdrawn,evidenceCode],()=>{evidencePage.value=1;loadEvidence()})
watch(evidencePage,()=>{if(!evidenceLoading.value)loadEvidence()})
watch(()=>props.date,()=>{generation++;loader.cancel();closeHistory();evidenceLoader.cancel();evidenceHistoryLoader.cancel();result.value=null;evidence.value=null;evidencePage.value=1;evidenceHistoryId.value=0;withdrawId.value=0;working.value='';syncing.value=false;notice.value='';refresh();loadEvidence()})
watch(pinnedBatch,()=>{loader.cancel();closeHistory();refresh()})
onMounted(()=>{refresh();loadEvidence();timer=setInterval(()=>{if(!document.hidden&&!loading.value&&!working.value)refresh()},30000)})
onUnmounted(()=>{disposed=true;generation++;clearInterval(timer);loader.dispose();historyLoader.dispose();evidenceLoader.dispose();evidenceHistoryLoader.dispose()})
</script>

